from abc import ABC, abstractmethod


class SectionGeneric(ABC):

    @abstractmethod
    def _prepare_section_content(self, *args, **kwargs):
        pass

    @abstractmethod
    def generate_section_content(self, *args, **kwargs):
        """
        This function will merge prepared into proper format, which will be later handled by proper module
        :return: return config file content in proper format, e.g. str or dict
        """
        pass


class TextBasedSectionGeneric(SectionGeneric):
    def __init__(self, subsection_separator='\n'):
        self._section_content = []
        self._subsection_separator = subsection_separator

    def generate_section_content(self, *args, **kwargs):
        """
        This section can be common for epc / cus files, it will return formatted string for whole section
        :return: section string
        """
        self._prepare_section_content(*args, **kwargs)
        subsections = self._subsection_separator.join(['\n'.join(self._adjust_printing_style(subsection_lines))
                                                       for subsection_lines in self._section_content])

        return self._add_entry_lines() + subsections + self._add_exit_lines()

    @staticmethod
    def _add_entry_lines():
        """
        Add entry lines for subsection
        """
        return ''

    @staticmethod
    def _add_exit_lines():
        """
        Add exit lines for subsection
        """
        return ''

    def _adjust_printing_style(self, subsection_content):
        """
        :return: adjusted subsection content, for example printing width, or intending lines
        """
        return subsection_content

    @abstractmethod
    def _prepare_section_content(self, *args, **kwargs):
        pass
